def fusionner_equipements_en_double(apps, schema_editor):
    """`nom` devient unique : les doublons éventuels (même nom, casse ou espaces près) sont fusionnés
    en conservant le plus ancien, et les biens qui utilisaient un doublon sont rattachés à celui conservé."""
    Equipement = apps.get_model('gestion', 'Equipement')
    Bien = apps.get_model('gestion', 'Bien')
    gardes = {}
    for eq in Equipement.objects.order_by('id'):
        nom = ' '.join(eq.nom.split())
        cle = nom.lower()
        if cle not in gardes:
            gardes[cle] = eq
            if nom != eq.nom:
                eq.nom = nom
                eq.save(update_fields=['nom'])
            continue
        garde = gardes[cle]
        for bien in Bien.objects.filter(equipements=eq):
            bien.equipements.add(garde)
        eq.delete()


